    with t2:
        lotes = listar_lotes()
        if not lotes: st.warning("Cadastre um lote.")
        else:
            dict_l = {f"{l[1]} (ID {l[0]})": l[0] for l in lotes}
            with st.form("form_gta"):
                g1,g2 = st.columns(2)
                with g1:
                    lote_g  = st.selectbox("Lote", list(dict_l.keys()))
                    num_g   = st.text_input("Numero GTA *")
